/**
 * useQueue — polls GET /queue/status and distils from it what the player UI
 * needs:
 *   • llmTasks     — running LLM calls (chat/thought/respond) from
 *                    providers[*].chat_active. These are the "X is thinking …"
 *                    entries with model, iteration and duration estimate.
 *   • trackedTasks — tracked image/video/TTS/GPU tasks (active_tasks).
 *   • thinkingAgents — set of agent_names with an active LLM call (for the
 *                      "thinking …" indicator in the scene / on the avatar).
 *
 * plan-room-conversation phase 3 (make the feedback loop visible).
 */
import { useMemo } from 'react'
import { apiGet } from './api'
import { usePoll } from './usePolling'

export interface LLMTaskInfo {
  task_id?: string
  label?: string
  task_type?: string
  agent_name?: string
  model?: string
  provider_name?: string
  started_at?: string
  created_at?: string
  estimated_duration_s?: number
  iteration?: number
  max_iterations?: number
  status?: string
  duration_s?: number
  error?: string
}

export interface TrackedTaskInfo {
  task_id?: string
  label?: string
  task_type?: string
  agent_name?: string
  status?: string
  started_at?: string
  created_at?: string
  provider?: string
  queue_name?: string
  duration_s?: number
  error?: string
}

/** A finished task (LLM or tracked) for the "recently" block. */
export interface RecentTaskInfo {
  task_id?: string
  label?: string
  task_type?: string
  agent_name?: string
  status?: string
  duration_s?: number
  created_at?: string
  error?: string
  provider?: string
  model?: string
}

interface ProviderChannel {
  provider?: string
  type?: string
  serialize_group?: string
  healthy?: boolean
  chat_active?: LLMTaskInfo | LLMTaskInfo[] | null
  current_tasks?: LLMTaskInfo[]
  pending?: LLMTaskInfo[]
}

/** Availability of a backend (channel) for the status display.
 *  kind distinguishes LLM providers from image-generation backends. */
export interface ChannelStatus {
  key: string
  name: string
  healthy: boolean
  busy: boolean
  kind: 'llm' | 'image'
  /** Raw backend/provider type (civitai/together/openai_chat/
   *  openai_diffusion/a1111/…) for type-specific symbols in the panel. */
  type: string
  /** Serialize group of the channel (empty = no group). Channels with the
   *  same group run strictly one at a time. */
  group: string
  running: number
  waiting: number
}

// Generation-backend types (kind='image' — images AND video). Kept only as a
// fallback: the authoritative signal is the channel KEY ('backend:<name>'),
// so new backend types can never misclassify as LLM providers again.
const IMAGE_BACKEND_TYPES = new Set([
  'civitai', 'together', 'openai_chat', 'openai_diffusion', 'a1111', 'localai',
  'localai_video', 'together_video', 'openai_video',
])

// Non-LLM tasks that also run over provider channels (image/TTS) —
// they belong in the tracked active_tasks panel, NOT with the chat LLM calls.
const NON_LLM_TYPES = new Set([
  'image_generation', 'tts', 'video_generation', 'animate', 'variant_generation',
])

interface QueueStatus {
  providers?: Record<string, ProviderChannel>
  active_tasks?: TrackedTaskInfo[]
  recent?: LLMTaskInfo[]
  recent_tasks?: TrackedTaskInfo[]
}

/** Per agent: is an LLM call running, and is it a *reply* (vs. a thought)? */
export interface AgentActivity {
  responding: boolean
  label?: string
}

export interface QueueSnapshot {
  llmTasks: LLMTaskInfo[]
  /** Waiting LLM calls (providers[*].pending) — not started yet. */
  pendingLLM: LLMTaskInfo[]
  trackedTasks: TrackedTaskInfo[]
  /** Most recently finished tasks (LLM + tracked) for the "recently" block. */
  recent: RecentTaskInfo[]
  /** agent_name → activity (for the "replying …" / "thinking …" indicator). */
  agentActivity: Record<string, AgentActivity>
  /** LLM backends (channels) with availability + busy flag. */
  channels: ChannelStatus[]
}

const EMPTY: QueueSnapshot = {
  llmTasks: [], pendingLLM: [], trackedTasks: [], recent: [], agentActivity: {}, channels: [],
}

// task_types where the character is *replying* to someone (visible chat), as
// opposed to background thoughts.
const RESPONDING_TYPES = new Set(['character_talk', 'talk_to', 'send_message', 'chat_stream'])

function collectLLM(providers: Record<string, ProviderChannel> | undefined): LLMTaskInfo[] {
  const out: LLMTaskInfo[] = []
  const seen = new Set<string>()
  for (const ch of Object.values(providers || {})) {
    // chat_active (streaming/registered chats) + current_tasks (submit calls,
    // e.g. the loop respond via run_chat_turn) — both are running LLM calls.
    // Image/TTS tasks are filtered per-task via NON_LLM_TYPES below.
    const ca = ch?.chat_active
    const fromChat = Array.isArray(ca) ? ca : ca ? [ca] : []
    const fromCurrent = ch?.current_tasks || []
    for (const tk of [...fromChat, ...fromCurrent]) {
      if (NON_LLM_TYPES.has(tk.task_type || '')) continue
      const key = tk.task_id || `${tk.agent_name}:${tk.label}`
      if (seen.has(key)) continue
      seen.add(key)
      // provider_name is sometimes missing on the task → take it from the channel
      out.push({ ...tk, provider_name: tk.provider_name || ch?.provider })
    }
  }
  return out
}

/** Waiting (not yet started) LLM calls from providers[*].pending. */
function collectPendingLLM(providers: Record<string, ProviderChannel> | undefined): LLMTaskInfo[] {
  const out: LLMTaskInfo[] = []
  const seen = new Set<string>()
  for (const ch of Object.values(providers || {})) {
    for (const tk of ch?.pending || []) {
      if (NON_LLM_TYPES.has(tk.task_type || '')) continue
      const key = tk.task_id || `${tk.agent_name}:${tk.label}`
      if (seen.has(key)) continue
      seen.add(key)
      out.push({ ...tk, provider_name: tk.provider_name || ch?.provider })
    }
  }
  return out
}

/** "Recently": recently finished LLM calls (recent) + tracked tasks
 * (recent_tasks), merged and capped at 25 entries. */
function collectRecent(d: QueueStatus): RecentTaskInfo[] {
  const out: RecentTaskInfo[] = []
  for (const tk of d.recent || []) {
    out.push({
      task_id: tk.task_id, label: tk.label, task_type: tk.task_type, agent_name: tk.agent_name,
      status: tk.status, duration_s: tk.duration_s, created_at: tk.created_at, error: tk.error,
      provider: tk.provider_name, model: tk.model,
    })
  }
  for (const tk of d.recent_tasks || []) {
    out.push({
      task_id: tk.task_id, label: tk.label, task_type: tk.task_type, agent_name: tk.agent_name,
      status: tk.status, duration_s: tk.duration_s, created_at: tk.created_at, error: tk.error,
      provider: tk.provider,
    })
  }
  return out.slice(0, 25)
}

/** All backends (channels) from the providers payload: LLM providers AND
 * image-generation backends, distinguishable via `kind`. healthy/busy
 * come from the server (get_combined_status). */
function collectChannels(providers: Record<string, ProviderChannel> | undefined,
                         tracked: TrackedTaskInfo[] = []): ChannelStatus[] {
  // task_ids that already count as a channel task (chat_active/current_tasks),
  // so channel-submitted tracked tasks (e.g. Animate) are not counted twice.
  const channelIds = new Set<string>()
  for (const ch of Object.values(providers || {})) {
    const ca = ch?.chat_active
    const cas = Array.isArray(ca) ? ca : ca ? [ca] : []
    for (const tk of [...cas, ...(ch?.current_tasks || [])]) if (tk?.task_id) channelIds.add(tk.task_id)
  }
  const out: ChannelStatus[] = []
  for (const [key, ch] of Object.entries(providers || {})) {
    const type = (ch?.type || '').toLowerCase()
    // Backend channels are keyed 'backend:<name>' by the provider manager —
    // that key is the authoritative image/video-vs-LLM signal.
    const isImage = key.startsWith('backend:') || IMAGE_BACKEND_TYPES.has(type)
    const ca = ch?.chat_active
    const nChat = Array.isArray(ca) ? ca.length : ca ? 1 : 0
    const name = ch?.provider || key
    // Attribute tracked image/TTS tasks that were NOT channel-submitted (e.g. a
    // location image) to this channel by provider name, so the count shows up.
    const tr = tracked.filter(tk => (tk.provider || '') === name && !channelIds.has(tk.task_id || ''))
    const trackedWaiting = tr.filter(tk => (tk.status || '') === 'pending').length
    const trackedRunning = tr.length - trackedWaiting
    const running = nChat + (ch?.current_tasks?.length || 0) + trackedRunning
    const waiting = (ch?.pending?.length || 0) + trackedWaiting
    out.push({ key, name, healthy: !!ch?.healthy,
               busy: running > 0, kind: isImage ? 'image' : 'llm', type,
               group: (ch?.serialize_group || '').trim(), running, waiting })
  }
  // LLM providers first, then image backends; alphabetical within each group.
  out.sort((a, b) => (a.kind === b.kind ? a.name.localeCompare(b.name)
                                        : a.kind === 'llm' ? -1 : 1))
  return out
}

// One shared /queue/status feed for all consumers (TaskPanel, GenerationIndicator)
// via the central poll hub — a single fetch, visibility pause and error backoff.
// The fastest registered interval wins; TaskPanel passes 3000, the indicator 3000.
export function useQueue(intervalMs = 2000): QueueSnapshot {
  const { data } = usePoll<QueueStatus>(
    'queue-status', () => apiGet<QueueStatus>('/queue/status'), { intervalMs })

  return useMemo<QueueSnapshot>(() => {
    if (!data) return EMPTY
    const llmTasks = collectLLM(data.providers)
    const agentActivity: Record<string, AgentActivity> = {}
    for (const tk of llmTasks) {
      const name = (tk.agent_name || '').trim()
      if (!name) continue
      const responding = RESPONDING_TYPES.has(tk.task_type || '')
      // "responding" beats "thinking" if both run for the same agent
      if (!agentActivity[name] || responding) {
        agentActivity[name] = { responding, label: tk.label }
      }
    }
    return {
      llmTasks, pendingLLM: collectPendingLLM(data.providers),
      trackedTasks: data.active_tasks || [], recent: collectRecent(data), agentActivity,
      channels: collectChannels(data.providers, data.active_tasks || []),
    }
  }, [data])
}

/** Seconds since started_at (UTC ISO), or null when unknown. */
export function elapsedSeconds(startedAt: string | undefined, nowMs: number): number | null {
  if (!startedAt) return null
  const t = Date.parse(startedAt)
  if (isNaN(t)) return null
  return Math.max(0, Math.round((nowMs - t) / 1000))
}
